; ================================================
    ORG $0000  ; Sequential bank model

; Function: UPDATE_ROOM (Bank #1)
UPDATE_ROOM:
    JSR J1X_BUILTIN
    STD RESULT
    STD VAR_JOY_X
    LDD #30
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_JOY_X
    CMPD TMPVAL
    LBGT .CMP_44_TRUE
    LDD #0
    LBRA .CMP_44_END
.CMP_44_TRUE:
    LDD #1
.CMP_44_END:
    LBEQ IF_NEXT_63
    LDD >VAR_PLAYER_X
    STD TMPVAL          ; Save left operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_SPEED
    ADDD TMPVAL         ; D = D + LEFT (from TMPVAL)
    STD VAR_PLAYER_X
    LBRA IF_END_62
IF_NEXT_63:
    LDD #-30
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_JOY_X
    CMPD TMPVAL
    LBLT .CMP_45_TRUE
    LDD #0
    LBRA .CMP_45_END
.CMP_45_TRUE:
    LDD #1
.CMP_45_END:
    LBEQ IF_END_62
    LDD >VAR_PLAYER_X
    STD TMPVAL          ; Save left operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_SPEED
    STD TMPPTR      ; Save right operand to TMPPTR
    LDD TMPVAL      ; Get left operand from TMPVAL
    SUBD TMPPTR     ; Left - Right
    STD VAR_PLAYER_X
    LBRA IF_END_62
IF_END_62:
    ; CLAMP: Clamp value to range [min, max]
    LDD >VAR_PLAYER_X
    STD TMPPTR     ; Save value
    LDD #-90
    STD TMPPTR+2   ; Save min
    LDD #780
    STD TMPPTR+4   ; Save max
    LDD TMPPTR     ; Load value
    CMPD TMPPTR+2  ; Compare with min
    LBGE .CLAMP_0_CHK_MAX ; Branch if value >= min
    LDD TMPPTR+2
    STD RESULT
    LBRA .CLAMP_0_END
.CLAMP_0_CHK_MAX:
    LDD TMPPTR     ; Load value again
    CMPD TMPPTR+4  ; Compare with max
    LBLE .CLAMP_0_OK  ; Branch if value <= max
    LDD TMPPTR+4
    STD RESULT
    LBRA .CLAMP_0_END
.CLAMP_0_OK:
    LDD TMPPTR
    STD RESULT
.CLAMP_0_END:
    STD VAR_PLAYER_X
    ; CLAMP: Clamp value to range [min, max]
    LDD >VAR_PLAYER_X
    STD TMPPTR     ; Save value
    LDD #0
    STD TMPPTR+2   ; Save min
    LDD #670
    STD TMPPTR+4   ; Save max
    LDD TMPPTR     ; Load value
    CMPD TMPPTR+2  ; Compare with min
    LBGE .CLAMP_1_CHK_MAX ; Branch if value >= min
    LDD TMPPTR+2
    STD RESULT
    LBRA .CLAMP_1_END
.CLAMP_1_CHK_MAX:
    LDD TMPPTR     ; Load value again
    CMPD TMPPTR+4  ; Compare with max
    LBLE .CLAMP_1_OK  ; Branch if value <= max
    LDD TMPPTR+4
    STD RESULT
    LBRA .CLAMP_1_END
.CLAMP_1_OK:
    LDD TMPPTR
    STD RESULT
.CLAMP_1_END:
    STD VAR_SCROLL_X
    ; ===== SET_CAMERA_X builtin =====
    LDD >VAR_SCROLL_X
    STD >CAMERA_X    ; Store 16-bit camera X scroll offset
    LDD #0
    STD RESULT
    LDD #-1
    STD VAR_NEAR_HS
    LDD #0  ; const ROOM_ENTRANCE
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_CURRENT_ROOM
    CMPD TMPVAL
    LBEQ .CMP_46_TRUE
    LDD #0
    LBRA .CMP_46_END
.CMP_46_TRUE:
    LDD #1
.CMP_46_END:
    LBEQ IF_NEXT_65
    JSR TRAMP_CHECK_ENTRANCE_HOTSPOTS  ; cross-bank trampoline (bank #1 -> bank #0)
    LDD #-85
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_X
    CMPD TMPVAL
    LBLE .CMP_49_TRUE
    LDD #0
    LBRA .CMP_49_END
.CMP_49_TRUE:
    LDD #1
.CMP_49_END:
    LBEQ .LOGIC_48_FALSE
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_FLAGS_A
    STD TMPVAL          ; Save left operand to TMPVAL (stack-safe temp)
    LDD #2  ; const FL_TALLER_OPEN
    STD TMPPTR2     ; Save right operand to TMPPTR2
    LDD TMPVAL      ; Get left from TMPVAL
    ANDA TMPPTR2    ; A AND TMPPTR2+0 (high byte)
    ANDB TMPPTR2+1  ; B AND TMPPTR2+1 (low byte)
    CMPD TMPVAL
    LBNE .CMP_50_TRUE
    LDD #0
    LBRA .CMP_50_END
.CMP_50_TRUE:
    LDD #1
.CMP_50_END:
    LBEQ .LOGIC_48_FALSE
    LDD #1
    LBRA .LOGIC_48_END
.LOGIC_48_FALSE:
    LDD #0
.LOGIC_48_END:
    LBEQ .LOGIC_47_FALSE
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_MSG_TIMER
    CMPD TMPVAL
    LBEQ .CMP_51_TRUE
    LDD #0
    LBRA .CMP_51_END
.CMP_51_TRUE:
    LDD #1
.CMP_51_END:
    LBEQ .LOGIC_47_FALSE
    LDD #1
    LBRA .LOGIC_47_END
.LOGIC_47_FALSE:
    LDD #0
.LOGIC_47_END:
    LBEQ IF_NEXT_67
    LDD #5  ; const ROOM_CONSERVATORY
    STD VAR_ARG0
    JSR TRAMP_ENTER_ROOM  ; cross-bank trampoline (bank #1 -> bank #0)
    LBRA IF_END_66
IF_NEXT_67:
IF_END_66:
    LBRA IF_END_64
IF_NEXT_65:
    LDD #1  ; const ROOM_WORKSHOP
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_CURRENT_ROOM
    CMPD TMPVAL
    LBEQ .CMP_52_TRUE
    LDD #0
    LBRA .CMP_52_END
.CMP_52_TRUE:
    LDD #1
.CMP_52_END:
    LBEQ IF_NEXT_68
    JSR TRAMP_CHECK_WORKSHOP_HOTSPOTS  ; cross-bank trampoline (bank #1 -> bank #0)
    LDD #770
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_X
    CMPD TMPVAL
    LBGE .CMP_55_TRUE
    LDD #0
    LBRA .CMP_55_END
.CMP_55_TRUE:
    LDD #1
.CMP_55_END:
    LBEQ .LOGIC_54_FALSE
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_FLAGS_A
    STD TMPVAL          ; Save left operand to TMPVAL (stack-safe temp)
    LDD #16  ; const FL_PANEL_ACTIVE
    STD TMPPTR2     ; Save right operand to TMPPTR2
    LDD TMPVAL      ; Get left from TMPVAL
    ANDA TMPPTR2    ; A AND TMPPTR2+0 (high byte)
    ANDB TMPPTR2+1  ; B AND TMPPTR2+1 (low byte)
    CMPD TMPVAL
    LBNE .CMP_56_TRUE
    LDD #0
    LBRA .CMP_56_END
.CMP_56_TRUE:
    LDD #1
.CMP_56_END:
    LBEQ .LOGIC_54_FALSE
    LDD #1
    LBRA .LOGIC_54_END
.LOGIC_54_FALSE:
    LDD #0
.LOGIC_54_END:
    LBEQ .LOGIC_53_FALSE
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_MSG_TIMER
    CMPD TMPVAL
    LBEQ .CMP_57_TRUE
    LDD #0
    LBRA .CMP_57_END
.CMP_57_TRUE:
    LDD #1
.CMP_57_END:
    LBEQ .LOGIC_53_FALSE
    LDD #1
    LBRA .LOGIC_53_END
.LOGIC_53_FALSE:
    LDD #0
.LOGIC_53_END:
    LBEQ IF_NEXT_70
    LDD #6  ; const ROOM_VAULT_CORRIDOR
    STD VAR_ARG0
    JSR TRAMP_ENTER_ROOM  ; cross-bank trampoline (bank #1 -> bank #0)
    LBRA IF_END_69
IF_NEXT_70:
IF_END_69:
    LDD #690
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_X
    CMPD TMPVAL
